'use client';

import { useState } from 'react';
import type { ToolResultMessage } from '@earendil-works/pi-ai';
import { AlertCircleIcon, BrainIcon, CheckIcon, CircleSlashIcon } from 'lucide-react';
import { Spinner } from '@/components/ui/spinner';
import { Trace, TraceCollapsible, TraceCollapsibleContent, TraceCollapsibleTrigger, TraceDescription, TraceIcon, TraceLine, TraceTitle } from '@/components/ui/trace';
import { ToolCard, liveLabel } from './tool';
import type { ToolStatus } from './tool';
import type { Step } from './rows';
import { useChatText } from './labels';
import type { ChatLabels } from './labels';

type Image = Extract<ToolResultMessage['content'][number], { type: 'image' }>;
export type ActivityState = 'running' | 'done' | 'failed' | 'stopped';

const stepStatus = (step: Step): ToolStatus => step.kind === 'tool' ? step.entry.status : step.streaming ? 'running' : 'completed';

function summary(steps: readonly Step[], labels: ChatLabels): string | undefined {
  const counts = new Map<string, number>();
  for (const step of steps) if (step.kind === 'tool') counts.set(step.entry.call.name, (counts.get(step.entry.call.name) ?? 0) + 1);
  if (counts.size === 0 || counts.size > 4) return undefined;
  return [...counts].map(([name, count]) => `${labels.toolNoun(name)}${count > 1 ? ` ×${count}` : ''}`).join(' · ');
}

function header(steps: readonly Step[], state: ActivityState, streaming: boolean, labels: ChatLabels): string {
  if (state === 'running') {
    const running = steps.filter(step => stepStatus(step) === 'running');
    const current = streaming ? running[running.length - 1] : running[0];
    if (!current) return labels.thinkingStep;
    return current.kind === 'tool' ? liveLabel(current.entry.call, labels) : labels.thinkingStep;
  }
  if (state === 'failed') {
    const failed = steps.flatMap(step => step.kind === 'tool' && step.entry.status === 'failed' ? [step.entry.call.name] : []);
    return labels.activityFailed(failed.length, [...new Set(failed)].join(' · '));
  }
  const used = summary(steps, labels);
  const tools = steps.some(step => step.kind === 'tool');
  if (used === undefined && state !== 'stopped') return tools ? labels.activityMany(steps.length) : labels.activityThought;
  return labels.activityUsed(used ?? (tools ? labels.activityMany(steps.length) : labels.activityThought), state === 'stopped');
}

function Thinking({ text, streaming, details }: { readonly text: string; readonly streaming: boolean; readonly details: boolean }) {
  const { labels } = useChatText();
  const [open, setOpen] = useState(false);
  const line = <TraceLine {...(streaming ? { status: 'running' } : {})}>
    <TraceIcon><BrainIcon /></TraceIcon><TraceTitle>{streaming ? labels.thinking : labels.reasoning}</TraceTitle>
  </TraceLine>;
  return <TraceCollapsible data-testid="reasoning" data-state={open ? 'open' : 'closed'} data-streaming={streaming ? 'true' : undefined} open={details && open} onOpenChange={setOpen}>
    {details ? <TraceCollapsibleTrigger className="min-h-8 max-sm:min-h-11 pointer-coarse:min-h-11">{line}</TraceCollapsibleTrigger> : line}
    {details && <TraceCollapsibleContent><div data-testid="reasoning-text" className="max-h-72 overflow-y-auto text-sm whitespace-pre-wrap [overflow-wrap:anywhere]">{text}</div></TraceCollapsibleContent>}
  </TraceCollapsible>;
}

/** Presentation only: native Pi steps and host cards keep their existing ownership and order. */
export function ActivityBlock({ steps, state, streaming, developer, onOpenImage }: {
  readonly steps: readonly Step[]; readonly state: ActivityState; readonly streaming: boolean; readonly developer: boolean; readonly onOpenImage?: (image: Image) => void;
}) {
  const { labels } = useChatText();
  const [chosen, setChosen] = useState<boolean | undefined>();
  const open = chosen ?? state === 'failed';
  const Icon = state === 'running' ? Spinner : state === 'failed' ? AlertCircleIcon : state === 'stopped' ? CircleSlashIcon : CheckIcon;
  return <Trace data-testid="activity" data-boring="activity" data-state={state} data-open={open ? 'true' : 'false'} className="my-1.5">
    <TraceCollapsible open={open} onOpenChange={setChosen}>
      <TraceCollapsibleTrigger className="min-h-8 max-sm:min-h-11 pointer-coarse:min-h-11">
        <TraceLine {...(state === 'running' ? { status: 'running' } : state === 'failed' ? { status: 'error' } : {})}>
          <TraceIcon><Icon aria-hidden="true" /></TraceIcon>
          <TraceTitle data-testid="activity-label">{header(steps, state, streaming, labels)}</TraceTitle>
          <TraceDescription data-testid="activity-count">{labels.steps(steps.length)}</TraceDescription>
        </TraceLine>
      </TraceCollapsibleTrigger>
      <TraceCollapsibleContent>
        <Trace data-testid="activity-steps">
          {steps.map(step => <div key={step.key} data-testid="activity-step" data-kind={step.kind} data-status={stepStatus(step)}>
            {step.kind === 'tool'
              ? <ToolCard entry={step.entry} details={developer || step.entry.status === 'failed'} {...(onOpenImage ? { onOpenImage } : {})} />
              : <Thinking text={step.text} streaming={step.streaming} details={developer} />}
          </div>)}
        </Trace>
      </TraceCollapsibleContent>
    </TraceCollapsible>
  </Trace>;
}

'use client';

import { useEffect, useRef, useState } from 'react';
import { CheckIcon, CopyIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Item, ItemHeader, ItemTitle } from '@/components/ui/item';
import { copyText } from '../utils/utils';
import { useChatText } from './labels';

/** Copy button with a short "copied" confirmation. Failures stay visible as a title instead of throwing. */
export function CopyButton({ text, label: given, onCopy, className, iconOnly = false }: { readonly text: string; readonly label?: string; readonly onCopy?: (text: string) => Promise<void>; readonly className?: string; readonly iconOnly?: boolean }) {
  const { labels } = useChatText();
  const label = given ?? labels.copy;
  const [state, setState] = useState<'idle' | 'copied' | 'failed'>('idle');
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  const settle = (next: 'copied' | 'failed') => { setState(next); clearTimeout(timer.current); timer.current = setTimeout(() => setState('idle'), 1600); };
  return <Button variant="ghost" size={iconOnly ? 'icon-sm' : 'sm'} className={className} data-testid="copy" aria-label={label} title={state === 'failed' ? labels.copyFailed : label}
    onClick={() => { copyText(text, onCopy).then(() => settle('copied'), () => settle('failed')); }}>
    {state === 'copied' ? <CheckIcon data-icon="inline-start" /> : <CopyIcon data-icon="inline-start" />}
    <span className={iconOnly ? 'sr-only' : 'sr-only md:not-sr-only'}>{state === 'copied' ? labels.copied : state === 'failed' ? labels.failed : label}</span>
  </Button>;
}

/** Fenced code: language label, copy action, horizontal scroll. Text only, never interpreted as markup. */
export function CodeBlock({ code, language, onCopy }: { readonly code: string; readonly language?: string; readonly onCopy?: (text: string) => Promise<void> }) {
  const { labels } = useChatText();
  const label = language?.trim().split(/\s+/)[0]?.slice(0, 24);
  // shadcn's own Code Block installs a syntax highlighter (shiki) this block never uses, so the frame is an outline Item.
  return <Item variant="outline" size="xs" data-testid="code-block" className="my-3 flex-col items-stretch text-start">
    <ItemHeader>
      <ItemTitle data-testid="code-language" className="lowercase">{label || 'text'}</ItemTitle>
      <CopyButton text={code} label={labels.copyCode} {...(onCopy ? { onCopy } : {})} />
    </ItemHeader>
    <pre className="m-0 overflow-x-auto font-mono text-xs leading-5"><code>{code}</code></pre>
  </Item>;
}

'use client';

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { ChangeEvent, ClipboardEvent, ComponentProps, DragEvent, KeyboardEvent, ReactNode, Ref } from 'react';
import { AlertCircleIcon, FileTextIcon, Loader2Icon, MessageSquarePlusIcon, SlashIcon, XIcon } from 'lucide-react';
import { Attachment, AttachmentAction, AttachmentActions, AttachmentContent, AttachmentMedia, AttachmentTitle } from '@/components/ui/attachment';
import { Button } from '@/components/ui/button';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Input } from '@/components/ui/input';
import { InputGroup, InputGroupAddon, InputGroupTextarea } from '@/components/ui/input-group';
import { Toggle } from '@/components/ui/toggle';
import { hasMention, isLongPaste, mentionToken, mentionTrigger, removeMention, slashItems, slashQuery } from './config';
import type { AttachmentsConfig, MentionsConfig, PastedText, PasteToFile, SlashConfig, SlashItem } from './config';
import { useChatText } from './labels';
import { cn } from '../utils/utils';

export interface ComposerAttachment { readonly id: string; readonly name: string; readonly mimeType: string; readonly data: string }

const SAFE_IMAGE = /^image\/(png|jpe?g|gif|webp)$/;
const BASE64 = /^[A-Za-z0-9+/=\s]+$/;
/** A data URL for a thumbnail, only for common image types and well-formed base64. */
export function thumbnail(mimeType: string, data: string): string | undefined {
  return SAFE_IMAGE.test(mimeType) && BASE64.test(data) ? `data:${mimeType};base64,${data}` : undefined;
}

/**
 * The optional annotate toggle (FEEDBACK.md, "UX"): one button in the composer's row that arms element targeting on the host's page,
 * and one count chip for the notes taken. Send attaches them. The host owns everything else (the registry `feedback` item's
 * `useComposerFeedback` returns this shape). Absent: the composer is unchanged.
 */
export interface ComposerFeedback {
  /** The annotate toggle: arms targeting on the page (point mode on touch and compact screens), or stops it when it is on. */
  readonly annotate: () => void;
  /** Annotating is on: the toggle shows pressed. */
  readonly active: boolean;
  /** Notes taken and waiting to be sent with the next message; above zero, Send is allowed with no text. */
  readonly count: number;
  /** Removes the notes (the count chip's remove button). */
  readonly clear: () => void;
  /** Send: the text to send instead, with the notes attached, or why they cannot be sent yet. */
  readonly attach: (text: string) => Promise<{ readonly kind: 'ok'; readonly text: string } | { readonly kind: 'refused'; readonly reason: string }>;
  /** The message carrying the notes was accepted. */
  readonly sent: () => void;
}

/** One file being uploaded (or that failed to upload), shown as a chip until it settles or is dismissed. */
export interface PendingUpload {
  readonly id: string; readonly name: string; readonly state: 'uploading' | 'failed'; readonly error?: string;
  /** A pasted text file: abandons the upload and puts the text back in the message (its restore button, or Ctrl+Z). */
  readonly cancel?: (() => void) | undefined;
  /** The message text right after the paste was accepted: Ctrl+Z restores only while the text is still this (any later edit leaves it alone). */
  readonly restoreWhile?: string | undefined;
}

export interface ComposerProps {
  /** `/` menu of commands and skills. Absent: no menu and no keyboard trigger. */
  readonly slash?: SlashConfig | undefined;
  /** Reports a failing command. */
  readonly onSlashError?: ((cause: unknown) => void) | undefined;
  /** `@` file picker. Absent: no picker. */
  readonly mentions?: MentionsConfig | undefined;
  /** Paths picked or uploaded as mentions; each shows as a chip while its `@path` is still in the text. */
  readonly mentionPaths?: readonly string[];
  readonly onMentionPicked?: ((path: string) => void) | undefined;
  readonly uploads?: readonly PendingUpload[];
  readonly onDismissUpload?: ((id: string) => void) | undefined;
  /** A paste above `pasteToFile`'s limits, taken by the composer: the host uploads it as a file. Absent: pastes stay inline. */
  readonly onPasteText?: ((paste: PastedText) => void) | undefined;
  readonly pasteToFile?: PasteToFile | undefined;
  /** Extra controls in the bar (the model and effort pill) and a short note beside them. */
  readonly barStart?: ReactNode;
  readonly barNote?: ReactNode;
  /** Optional host mode/model chips beside the attach control. */
  readonly chips?: ReactNode;
  /** Optional host context above the input. */
  readonly quote?: ReactNode;
  readonly text: string;
  readonly onText: (text: string) => void;
  readonly attachments: readonly ComposerAttachment[];
  /** Host-owned content contributes to send readiness. */
  readonly hasFiles?: boolean;
  readonly onRemoveAttachment: (id: string) => void;
  /** The agent is working: the primary button stops it and Enter queues the message (steering is chosen on the queued message). */
  readonly working: boolean;
  /** A send would be refused right now (not connected, a submission in flight, uploading). */
  readonly sendBlocked: boolean;
  readonly disabled: boolean;
  readonly stopRequested: boolean;
  readonly onSend: () => void;
  readonly onStop: () => void;
  readonly uploading: boolean;
  readonly canAttach: boolean;
  /** The phone camera sheet (`attachments.Camera`, from `pi-chat-attachments`). Without it there is no Take a photo entry. */
  readonly camera?: AttachmentsConfig['Camera'];
  readonly fileAccept: string;
  readonly onPickFiles: (files: readonly File[]) => void;
  readonly onKeyDown?: ((event: KeyboardEvent<HTMLTextAreaElement>) => void) | undefined;
  readonly textareaRef: Ref<HTMLTextAreaElement>;
  readonly placeholder?: string;
  /** `card` (default): chips, then full-width text, then a row of controls, in the host's shadcn InputGroup. `pill` puts the text between
   * the controls on one row. `stacked` and `inline` are compatibility values that render as `card`. */
  readonly layout?: 'card' | 'pill' | 'stacked' | 'inline';
  /** Host controls (for example a voice button) as round buttons between the model pill and the send button. */
  readonly barEnd?: ReactNode;
  /** Host controls at the very left edge of the bar, before "+" (`PiChat`'s `composerStart`). */
  readonly start?: ReactNode;
  /** A control shown in place of Send while there is nothing to send (WhatsApp's microphone): Send comes back as soon as there is text or a file. */
  readonly whenEmpty?: ReactNode;
  /** The optional Feedback button and chip. */
  readonly feedback?: ComposerFeedback | undefined;
}

/** The annotate toggle beside the "+" menu in both layouts. */
function AnnotateButton({ feedback, disabled }: { readonly feedback: ComposerFeedback; readonly disabled: boolean }) {
  const { labels } = useChatText();
  return <Toggle className="min-h-11 min-w-11" data-testid="composer-annotate" pressed={feedback.active} disabled={disabled}
    aria-label={labels.annotate} title={labels.annotateHint} onPressedChange={() => feedback.annotate()}>
    <MessageSquarePlusIcon data-icon="inline-start" aria-hidden="true" />
  </Toggle>;
}

/**
 * One chip above the text (a mention, an upload, an attachment or the notes count) as the host's shadcn Attachment. The remove
 * buttons keep a 44px touch target on coarse pointers; negative margins let it extend beyond the chip instead of growing it.
 */
function Chip({ media, image = false, label, actions, ...props }: ComponentProps<typeof Attachment> & { readonly media: ReactNode; readonly image?: boolean; readonly label: ReactNode; readonly actions?: ReactNode }) {
  return <Attachment size="xs" role="listitem" {...props}>
    <AttachmentMedia variant={image ? 'image' : 'icon'}>{media}</AttachmentMedia>
    <AttachmentContent><AttachmentTitle>{label}</AttachmentTitle></AttachmentContent>
    {actions && <AttachmentActions className="max-sm:-my-2.5 pointer-coarse:-my-2.5">{actions}</AttachmentActions>}
  </Attachment>;
}

function RemoveChip({ label, onClick }: { readonly label: string; readonly onClick: () => void }) {
  return <AttachmentAction aria-label={label} title={label} onClick={onClick}><XIcon aria-hidden="true" /></AttachmentAction>;
}

/** The count chip: how many notes go with the next message, and a way to drop them. */
function NotesChip({ feedback }: { readonly feedback: ComposerFeedback }) {
  const { labels } = useChatText();
  return <Chip data-testid="feedback-count" data-count={feedback.count} media={<MessageSquarePlusIcon aria-hidden="true" />} label={labels.annotateNotes(feedback.count)}
    actions={<AttachmentAction data-testid="feedback-count-clear" aria-label={labels.annotateClear} title={labels.annotateClear} onClick={() => feedback.clear()}><XIcon aria-hidden="true" /></AttachmentAction>} />;
}

/** Whether a file input's `accept` admits a JPEG photo (empty admits everything). */
export function acceptsPhotos(accept: string): boolean {
  const tokens = accept.split(',').map(token => token.trim().toLowerCase()).filter(Boolean);
  return tokens.length === 0 || tokens.some(token => token === 'image/*' || token === '*/*' || token === 'image/jpeg' || token === '.jpg' || token === '.jpeg');
}

/** True on a touch-first device (a phone or tablet); false on the server, so the menu renders the same there. */
function useCoarsePointer(): boolean {
  const [coarse, setCoarse] = useState(() => globalThis.matchMedia?.('(pointer: coarse)').matches ?? false);
  useEffect(() => {
    const query = globalThis.matchMedia?.('(pointer: coarse)');
    if (!query) return;
    const update = () => setCoarse(query.matches);
    update();
    query.addEventListener?.('change', update);
    return () => query.removeEventListener?.('change', update);
  }, []);
  return coarse;
}

/** The "+" button and the host's shadcn dropdown menu (Attach files, Take a photo, Commands). */
function PlusActions({ disabled, onAttach, onTakePhoto, onCommands, textarea }: { readonly disabled: boolean; readonly onAttach?: (() => void) | undefined; readonly onTakePhoto?: (() => void) | undefined; readonly onCommands?: (() => void) | undefined; readonly textarea: { readonly current: HTMLTextAreaElement | null } }) {
  const { labels, icons } = useChatText();
  const [open, setOpen] = useState(false);
  // Commands puts `/` in the message: focus goes back to the text, not to the "+" button.
  const toText = useRef(false);
  useEffect(() => { if (disabled) setOpen(false); }, [disabled]);
  return <DropdownMenu open={open} onOpenChange={setOpen}>
    <DropdownMenuTrigger render={<Button variant="ghost" size="icon" />} data-testid="composer-plus" aria-label={labels.add} title={labels.add} disabled={disabled}>
      <icons.add data-icon="inline-start" aria-hidden="true" /></DropdownMenuTrigger>
    <DropdownMenuContent side="top" align="start" aria-label={labels.add} data-testid="composer-plus-menu" className="w-52"
      finalFocus={() => { const text = toText.current; toText.current = false; return text ? textarea.current : true; }}>
      {onAttach && <DropdownMenuItem data-testid="composer-attach" onClick={onAttach} className="max-sm:min-h-11 pointer-coarse:min-h-11">
        <icons.attach aria-hidden="true" />{labels.attachFiles}</DropdownMenuItem>}
      {onTakePhoto && <DropdownMenuItem data-testid="composer-take-photo" onClick={onTakePhoto} className="max-sm:min-h-11 pointer-coarse:min-h-11">
        <icons.camera aria-hidden="true" />{labels.takePhoto}</DropdownMenuItem>}
      {onCommands && <DropdownMenuItem data-testid="composer-commands" onClick={() => { toText.current = true; onCommands(); }} className="max-sm:min-h-11 pointer-coarse:min-h-11">
        <SlashIcon aria-hidden="true" />{labels.commands}</DropdownMenuItem>}
    </DropdownMenuContent>
  </DropdownMenu>;
}

const MAX_HEIGHT = 208;

/** Prompt composer: auto-growing textarea, Enter to send, one primary Send/Stop button. While the agent works a message is queued. */
export function Composer(props: ComposerProps) {
  const { text, attachments, working, sendBlocked, disabled, stopRequested, uploading, canAttach, layout = 'card' } = props;
  const { labels, icons } = useChatText();
  const inner = useRef<HTMLTextAreaElement | null>(null);
  const composing = useRef(false);
  const [dragging, setDragging] = useState(false);
  const [caret, setCaret] = useState(0);
  // A menu closed with Escape stays closed until the text changes.
  const [dismissed, setDismissed] = useState<string | null>(null);
  useEffect(() => { setDismissed(value => value === null || value === text ? value : null); }, [text]);
  const pendingCaret = useRef<number | null>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  // The camera sheet lives here, not in the menu: the menu content unmounts as soon as it closes.
  const [cameraOpen, setCameraOpen] = useState(false);
  const coarse = useCoarsePointer();
  // A feature shows only when its config carries the component that draws it (`pi-chat-slash`, `pi-chat-mentions`, `pi-chat-attachments`).
  const Camera = props.camera, Slash = props.slash?.Picker, Mention = props.mentions?.Picker;
  const canPhoto = canAttach && coarse && acceptsPhotos(props.fileAccept) && Camera !== undefined;
  const slash = Slash ? props.slash : undefined, mentions = Mention ? props.mentions : undefined;
  const items = useMemo<SlashItem[]>(() => slash ? slashItems(slash) : [], [slash]);
  const setRef = (element: HTMLTextAreaElement | null) => {
    inner.current = element;
    if (typeof props.textareaRef === 'function') props.textareaRef(element); else if (props.textareaRef) (props.textareaRef as { current: HTMLTextAreaElement | null }).current = element;
  };
  useLayoutEffect(() => {
    const element = inner.current;
    if (!element) return;
    const resize = () => {
      element.style.height = 'auto';
      element.style.height = `${Math.min(element.scrollHeight, MAX_HEIGHT)}px`;
      element.style.overflowY = element.scrollHeight > MAX_HEIGHT ? 'auto' : 'hidden';
    };
    resize();
    if (pendingCaret.current !== null) { element.setSelectionRange(pendingCaret.current, pendingCaret.current); element.focus(); pendingCaret.current = null; }
    if (typeof ResizeObserver === 'undefined') return;
    let width = element.clientWidth;
    const observer = new ResizeObserver(() => {
      const next = element.clientWidth;
      if (next === width) return;
      width = next; resize();
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, [text]);

  const query = slash && items.length ? slashQuery(text, caret) : null;
  const trigger = query === null && mentions ? mentionTrigger(text, caret) : null;
  const slashOpen = query !== null && dismissed !== text, mentionOpen = trigger !== null && dismissed !== text;
  const menuOpen = slashOpen || mentionOpen;
  const edit = (next: string, position: number) => { pendingCaret.current = position; setCaret(position); props.onText(next); };
  const trackCaret = (element: HTMLTextAreaElement) => setCaret(element.selectionStart ?? element.value.length);
  const dismiss = () => setDismissed(text);
  const pickSlash = (item: SlashItem) => {
    const rest = text.slice(caret).replace(/^\s+/, '');
    if (item.source === 'skill') return edit(`/${item.name} ${rest}`, item.name.length + 2);
    const command = slash?.commands?.find(candidate => candidate.name === item.name);
    props.onText(rest); setCaret(0);
    inner.current?.focus();
    if (!command) return;
    try { void Promise.resolve(command.run({ text: rest, setText: value => props.onText(value) })).catch(cause => props.onSlashError?.(cause)); }
    catch (cause) { props.onSlashError?.(cause); }
  };
  const pickMention = (path: string) => {
    if (!trigger) return;
    const token = `${mentionToken(path)} `;
    edit(`${text.slice(0, trigger.start)}${token}${text.slice(trigger.end)}`, trigger.start + token.length);
    props.onMentionPicked?.(path);
  };
  const openCommands = () => edit(`${text}${text && !/\s$/.test(text) ? ' ' : ''}/`, text.length + (text && !/\s$/.test(text) ? 2 : 1));
  const chips = (props.mentionPaths ?? []).filter(path => hasMention(text, path));
  const onChange = (event: ChangeEvent<HTMLTextAreaElement>) => { trackCaret(event.currentTarget); props.onText(event.currentTarget.value); };

  const { feedback } = props;
  const hasContent = text.trim().length > 0 || attachments.length > 0 || props.hasFiles || (feedback?.count ?? 0) > 0;
  const canSubmit = hasContent && !sendBlocked && !disabled;
  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    props.onKeyDown?.(event);
    if (event.defaultPrevented) return;
    // Ctrl+Z right after a paste that is still uploading puts the pasted text back, instead of undoing the paste in the textarea.
    const undo = (props.uploads ?? []).filter(item => item.state === 'uploading' && item.cancel && item.restoreWhile === props.text).pop();
    if (undo && (event.ctrlKey || event.metaKey) && !event.shiftKey && !event.altKey && event.key.toLowerCase() === 'z') { event.preventDefault(); undo.cancel!(); return; }
    // Never send while an input method editor is composing (Enter confirms the candidate).
    // A phone keyboard has no Shift+Enter: on a touch device Enter inserts a newline and the Send button sends.
    const touch = globalThis.matchMedia?.('(pointer: coarse)').matches === true;
    if (event.key === 'Enter' && !touch && !event.shiftKey && !composing.current && !event.nativeEvent.isComposing && event.keyCode !== 229) {
      event.preventDefault();
      if (canSubmit) props.onSend();
    }
  };
  const onPaste = (event: ClipboardEvent<HTMLTextAreaElement>) => {
    if (canAttach && event.clipboardData.files.length) { event.preventDefault(); props.onPickFiles(Array.from(event.clipboardData.files)); return; }
    if (!props.onPasteText) return;
    const pasted = event.clipboardData.getData('text/plain');
    if (!isLongPaste(pasted, props.pasteToFile)) return;
    event.preventDefault();
    props.onPasteText({ text: pasted, start: event.currentTarget.selectionStart, end: event.currentTarget.selectionEnd });
  };
  const drag = (event: DragEvent) => { if (canAttach) { event.preventDefault(); setDragging(event.type === 'dragover'); } };
  const drop = (event: DragEvent) => { if (!canAttach) return; event.preventDefault(); setDragging(false); props.onPickFiles(Array.from(event.dataTransfer.files)); };

  const chipList = (props.quote || chips.length > 0 || (props.uploads?.length ?? 0) > 0 || (feedback?.count ?? 0) > 0 || attachments.length > 0) && <>
    {props.quote}
    {feedback && feedback.count > 0 && <div role="list" className="contents"><NotesChip feedback={feedback} /></div>}
    {chips.length > 0 && <div role="list" data-testid="mention-chips" aria-label={labels.mentionedFiles} className="contents">
      {chips.map(path => <Chip key={path} data-testid="mention-chip" data-path={path} title={props.mentions?.label?.(path) ?? path} className="max-w-full sm:max-w-[16rem]"
        media={props.mentions?.icon ?? <FileTextIcon aria-hidden="true" />}  label={props.mentions?.label?.(path) ?? path} actions={<RemoveChip label={labels.remove(props.mentions?.label?.(path) ?? path)} onClick={() => props.onText(removeMention(text, path))} />} />)}
    </div>}
    {(props.uploads?.length ?? 0) > 0 && <div role="list" data-testid="uploads" aria-label={labels.uploads} className="contents">
      {props.uploads!.map(item => <Chip key={item.id} data-testid="upload-chip" state={item.state === 'failed' ? 'error' : 'uploading'} data-state={item.state} title={item.error ?? item.name} className="max-w-full sm:max-w-[20rem]"
        media={item.state === 'failed' ? <AlertCircleIcon className="text-destructive" aria-hidden="true" /> : <Loader2Icon className="animate-spin motion-reduce:animate-none" aria-hidden="true" />}
        label={item.state === 'failed' ? labels.uploadFailed(item.name, item.error) : labels.uploading(item.name)}
        actions={<>
          {item.cancel && <RemoveChip label={labels.restorePaste} onClick={() => item.cancel!()} />}
          {item.state === 'failed' && <RemoveChip label={labels.dismiss(item.name)} onClick={() => props.onDismissUpload?.(item.id)} />}
        </>} />)}
    </div>}
    {attachments.length > 0 && <div role="list" data-testid="attachments" aria-label={labels.attachments} className="contents">
      {attachments.map(attachment => {
        const src = thumbnail(attachment.mimeType, attachment.data);
        return <Chip key={attachment.id} data-testid="attachment" className="max-w-full sm:max-w-[14rem]" image={!!src}
          media={src ? <img src={src} alt="" /> : <FileTextIcon aria-hidden="true" />} label={attachment.name}
          actions={<RemoveChip label={labels.remove(attachment.name)} onClick={() => props.onRemoveAttachment(attachment.id)} />} />;
      })}
    </div>}
  </>;
  const pill = layout === 'pill';
  const textareaEl = <InputGroupTextarea ref={setRef} data-testid="composer-input" aria-label={labels.messageInput} rows={1} value={text} disabled={disabled}
      placeholder={props.placeholder ?? (working ? labels.placeholderWorking : labels.placeholder)}
      {...(slash || mentions ? { role: 'combobox', 'aria-expanded': menuOpen, 'aria-haspopup': 'listbox', 'aria-autocomplete': 'list' } as const : {})}
      onChange={onChange} onKeyDown={onKeyDown} onPaste={onPaste} onKeyUp={event => trackCaret(event.currentTarget)} onClick={event => trackCaret(event.currentTarget)}
      onCompositionStart={() => { composing.current = true; }} onCompositionEnd={() => { composing.current = false; }}
      className={pill ? 'max-h-52 min-h-0 min-w-0' : 'max-h-52 min-h-11'} />;
  const plus = (canAttach || items.length > 0) && <PlusActions disabled={disabled} textarea={inner} onAttach={canAttach ? () => fileInput.current?.click() : undefined} onTakePhoto={canPhoto ? () => setCameraOpen(true) : undefined} onCommands={items.length > 0 ? openCommands : undefined} />;
  // One child slot either way, so a composer without `start` keeps its exact markup (React ids included).
  const startAndPlus = props.start ? <><div data-testid="composer-start" className="flex shrink-0 items-center gap-1">{props.start}</div>{plus}</> : plus;
  const fileEl = canAttach && <Input ref={fileInput} type="file" multiple accept={props.fileAccept} disabled={disabled} tabIndex={-1} aria-hidden="true" className="sr-only" data-testid="composer-file" data-attach="true"
    onChange={event => { const files = Array.from(event.currentTarget.files ?? []); event.currentTarget.value = ''; props.onPickFiles(files); }} />;
  const send = working
    ? <Button variant="default" size="icon" data-testid="composer-submit" data-state="stop" aria-label={labels.stop} title={labels.stop} disabled={disabled || stopRequested} onClick={props.onStop} className="shrink-0">
      {stopRequested ? <Loader2Icon data-icon="inline-start" className="animate-spin motion-reduce:animate-none" aria-hidden="true" /> : <icons.stop data-icon="inline-start" aria-hidden="true" />}</Button>
    : props.whenEmpty && !hasContent ? <div data-testid="composer-when-empty" className="flex shrink-0 items-center">{props.whenEmpty}</div>
    : <Button variant="default" size="icon" type="submit" data-testid="composer-submit" data-state="send" aria-label={labels.send} title={labels.sendHint} disabled={!canSubmit} className="shrink-0">
      <icons.send data-icon="inline-start" aria-hidden="true" /></Button>;
  const end = <>
    {props.barStart}
    {props.chips && <div className="flex min-w-0 items-center gap-2">{props.chips}</div>}
    {props.barNote}
    {uploading && !(props.uploads?.length) && <span role="status" className="inline-flex items-center gap-1 text-xs text-muted-foreground"><Loader2Icon className="size-3 animate-spin motion-reduce:animate-none" aria-hidden="true" />{labels.preparingAttachments}</span>}
    {!pill && <span className="min-w-0 flex-1" />}
    {props.barEnd && <div data-testid="composer-tools" className="flex shrink-0 items-center gap-2">{props.barEnd}</div>}
    {working && hasContent && <Button variant="ghost" size="icon" data-testid="composer-queue" aria-label={labels.queue} title={labels.queue} disabled={!canSubmit} onClick={props.onSend} className="shrink-0">
      <icons.queue data-icon="inline-start" aria-hidden="true" /></Button>}
    {send}
  </>;

  // One shadcn InputGroup: the chips, the text and a row of controls (`card`, also used for the `stacked` and `inline` compatibility
  // values), or one row with the text between the controls (`pill`, chips above it). Its look is the host's; ours is layout only.
  return <form data-testid="composer" data-layout={layout} data-dragging={dragging || undefined} onSubmit={event => { event.preventDefault(); if (canSubmit) props.onSend(); }} onDragOver={drag} onDragLeave={drag} onDrop={drop}
    className={cn('relative flex flex-col gap-2', pill && '@container/composer')}>
    {fileEl}
    {slashOpen && Slash && <Slash query={query!} items={items} onSelect={pickSlash} onDismiss={dismiss} />}
    {mentionOpen && mentions && Mention && <Mention query={trigger!.query} listLabel={mentions.listLabel} renderOption={mentions.renderOption} search={mentions.search} generation={mentions.generation} onSelect={pickMention} onDismiss={dismiss} />}
    {pill && chipList && <div className="flex flex-wrap gap-2">{chipList}</div>}
    {pill ? <InputGroup>
      <InputGroupAddon>{startAndPlus}{feedback && <AnnotateButton feedback={feedback} disabled={disabled} />}</InputGroupAddon>
      {textareaEl}
      <InputGroupAddon align="inline-end" data-testid="composer-controls">{end}</InputGroupAddon>
    </InputGroup> : <InputGroup>
      {chipList && <InputGroupAddon align="block-start" className="flex-wrap">{chipList}</InputGroupAddon>}
      {textareaEl}
      <InputGroupAddon align="block-end" data-testid="composer-controls">
        {startAndPlus}
        {feedback && <AnnotateButton feedback={feedback} disabled={disabled} />}
        {end}
      </InputGroupAddon>
    </InputGroup>}
    {cameraOpen && Camera && <Camera onClose={() => setCameraOpen(false)} onCapture={file => { setCameraOpen(false); props.onPickFiles([file]); }} />}
  </form>;
}

'use client';

import { useEffect, useState } from 'react';
import { FileTextIcon, ShapesIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Drawer, DrawerContent, DrawerTitle, DrawerTrigger } from '@/components/ui/drawer';
import { DropdownMenu, DropdownMenuContent, DropdownMenuGroup, DropdownMenuItem, DropdownMenuLabel, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { useChatText } from './labels';

/** A conversation's observed file, opened only through the host's existing callback. */
export interface ConversationFile {
  readonly id: string;
  readonly name: string;
  readonly open: (() => void) | undefined;
}

/** Conversation files, not a second workspace: the native menu on desktop and the installed drawer on phones. */
export function ConversationFiles({ files }: { readonly files: readonly ConversationFile[] }) {
  const { labels } = useChatText();
  const [open, setOpen] = useState(false);
  const [phone, setPhone] = useState(() => globalThis.matchMedia?.('(max-width: 640px)').matches === true);
  useEffect(() => {
    const media = globalThis.matchMedia?.('(max-width: 640px)');
    if (!media) return;
    const change = () => { setPhone(media.matches); setOpen(false); };
    media.addEventListener('change', change);
    return () => media.removeEventListener('change', change);
  }, []);
  const available = files.filter(file => file.open);
  if (!available.length) return null;
  const trigger = <Button variant="outline" data-testid="conversation-files" className="mb-3 max-w-full gap-2"><ShapesIcon data-icon="inline-start" aria-hidden="true" />{labels.artifacts}<span className="text-muted-foreground">· {available.length}</span></Button>;
  const label = (file: ConversationFile) => <><FileTextIcon data-icon="inline-start" className="shrink-0" aria-hidden="true" /><span className="min-w-0 truncate">{file.name}</span></>;
  const select = (file: ConversationFile) => { setOpen(false); file.open?.(); };
  return phone ? <Drawer open={open} onOpenChange={setOpen} showSwipeHandle><DrawerTrigger render={trigger} /><DrawerContent data-testid="conversation-files-list" className="pi-chat max-h-[80dvh]">
    <div className="flex min-h-0 flex-col px-2 pt-2 pb-[env(safe-area-inset-bottom)]"><div className="px-2"><DrawerTitle className="m-0">{labels.artifacts}</DrawerTitle></div>
      <ul className="m-0 max-h-[60dvh] list-none overflow-y-auto p-0">{available.map(file => <li key={file.id} className="flex min-h-12"><Button variant="ghost" size="sm" data-testid="conversation-file" data-file={file.id} className="h-auto w-full justify-start gap-2 text-start" onClick={() => select(file)}>{label(file)}</Button></li>)}</ul>
    </div></DrawerContent></Drawer>
    : <DropdownMenu open={open} onOpenChange={setOpen}><DropdownMenuTrigger render={trigger} /><DropdownMenuContent side="top" align="start" sideOffset={6} data-testid="conversation-files-list" aria-label={labels.artifacts} onKeyDown={event => { if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); setOpen(false); } }} className="pi-chat w-80 max-w-[calc(100vw-32px)]">
      <DropdownMenuGroup className="max-h-[60dvh] overflow-y-auto"><DropdownMenuLabel>{labels.artifacts}</DropdownMenuLabel>
        {available.map(file => <DropdownMenuItem key={file.id} data-testid="conversation-file" data-file={file.id} className="min-h-8 pointer-coarse:min-h-12" onClick={() => select(file)}>{label(file)}</DropdownMenuItem>)}
      </DropdownMenuGroup></DropdownMenuContent></DropdownMenu>;
}

import type { ComponentType, ReactNode } from 'react';
import type { ToolCall, ToolResultMessage } from '@earendil-works/pi-ai';
import type { ChatController } from '@hachej/boring-ui-kit/native-chat';
import type { BlockAction } from '../button/actions';
import type { ChatLabels } from './labels';

/*
 * Composer features the host switches on by configuration. Each prop is optional: leave it out and the composer has
 * no menu, no button and no keyboard trigger for it. The current model and thinking level are read from the native
 * view's `pi.agent` document, so there is no extra state to keep in sync. The component that draws a feature comes from its own
 * registry item and rides on the config (`Picker`, `Camera`, `useRecorder` with `Button` and `Bubble`): without it the feature is
 * simply not offered (no menu, no pill, no camera entry, no record button). `withChatPlugins` of `pi-chat-plugins` fills them all in.
 */

/** Where a `/` menu entry comes from. Skills and host commands are grouped separately in the menu. */
export type SlashSource = 'local' | 'extension' | 'prompt' | 'skill';

export interface SlashApi {
  /** Replace the composer text. */
  readonly setText: (text: string) => void;
  /** The composer text with the typed `/query` already removed. */
  readonly text: string;
}
export interface SlashCommand {
  readonly name: string;
  readonly description?: string;
  /** Shown as a badge and as a filter chip; commands without one are grouped as `built-in`. */
  readonly sourcePlugin?: string;
  readonly run: (api: SlashApi) => void | Promise<void>;
}
export interface SlashSkill {
  readonly name: string;
  readonly description: string;
  readonly sourcePlugin?: string;
}
export interface SlashConfig {
  readonly commands?: readonly SlashCommand[];
  readonly skills?: readonly SlashSkill[];
  /** The `/` menu (`SlashPicker` of `pi-chat-slash`). Without it there is no `/` menu and no Commands entry. */
  readonly Picker?: ComponentType<SlashPickerProps> | undefined;
}

export interface MentionResult { readonly path: string; readonly kind?: 'file' | 'directory'; readonly label?: string }
export interface MentionsConfig {
  /** Accessible name and optional option/media presentation for a host catalog. */
  readonly listLabel?: string;
  readonly icon?: ReactNode;
  readonly renderOption?: (item: MentionResult, query: string) => ReactNode;
  readonly label?: (id: string) => string;
  /** Workspace search for the `@` picker. Empty `query` asks for a default listing. Abort `signal` when the query changes. */
  readonly search: (query: string, signal: AbortSignal) => Promise<readonly MentionResult[]>;
  /** Open a mentioned workspace file (for example in the right panel). When given, a mention in a sent message is a button. */
  readonly open?: ((path: string) => void) | undefined;
  /** Changes whenever what `search` would return may have changed (a workspace change event, another workspace). An open picker searches again. */
  readonly generation?: string | number | undefined;
  /** Host-supplied look for a mention in a sent message (a plug-in such as feedback). Return undefined to keep the default mention. */
  readonly render?: ((path: string) => ReactNode | undefined) | undefined;
  /** Sent-message rendering, independent of the composer's token presentation. */
  readonly renderSent?: ((path: string) => ReactNode | undefined) | undefined;
  /**
   * Upload bytes through the host's provider. Image cards read thumbnails; voice bubbles read audio only on Play.
   * Thumbnails accept png, jpeg, gif and webp. Audio must retain its recorded audio MIME type.
   */
  readonly preview?: PreviewRead | undefined;
  /** Optional authorized playback URL, requested only on Play; otherwise voice audio uses `preview`. */
  readonly audioUrl?: AudioUrlRead | undefined;
  /** The `@` picker (`MentionPicker` of `pi-chat-mentions`). Without it typing `@` opens nothing. */
  readonly Picker?: ComponentType<MentionPickerProps> | undefined;
}
export type AudioUrlRead = (path: string, signal: AbortSignal) => Promise<string | undefined>;
/** Reads an upload for its thumbnail or lazy voice playback: its media type and base64 data, or undefined. */
export type PreviewRead = (path: string, signal: AbortSignal) => Promise<{ readonly mimeType: string; readonly data: string } | undefined>;

/** Paste-to-file thresholds: a paste with more characters or more lines than these becomes a file. Defaults 2000 and 40. */
export interface PasteToFile { readonly minChars?: number | undefined; readonly minLines?: number | undefined }
/** A paste the composer took, with the textarea range it replaces (restored if the upload is cancelled). */
export interface PastedText { readonly text: string; readonly start: number; readonly end: number }

export interface UploadResult {
  /** The host saved the file in the workspace: it becomes an `@path` mention. */
  readonly path?: string;
  /** Sent as a native image attachment instead of a path mention when both are supplied. */
  readonly image?: { readonly data: string; readonly mimeType: string };
  readonly name: string;
}
export interface VoiceMessageConfig {
  readonly transcribe: (audio: Blob, signal: AbortSignal) => Promise<string>;
  /** Capture limit (default five minutes). Upload and send still wait for release. */
  readonly maxMs?: number;
  /** Same workspace upload contract as `attachments.upload`, used instead when supplied. Preserve the voice- filename prefix. */
  readonly upload?: AttachmentsConfig['upload'];
  /** The recorder (`useVoiceMessage` of `pi-chat-voice`). Without it there is no voice message: no button, no pending bubble. */
  readonly useRecorder?: VoiceRecorderHook | undefined;
  /** The hold-to-record button at the end of the composer bar (`VoiceMessageButton` of `pi-chat-voice`). */
  readonly Button?: ComponentType<VoiceMessageButtonProps> | undefined;
  /** A voice message on its way: recording, transcribing, uploading (`PendingVoiceBubble` of `pi-chat-voice`). */
  readonly Bubble?: ComponentType<PendingVoiceBubbleProps> | undefined;
}

export interface AttachmentsConfig {
  /** The file input's `accept`. Any file when omitted. */
  readonly accept?: string;
  readonly upload: (files: File[], signal: AbortSignal) => Promise<readonly UploadResult[]>;
  /** The full-screen camera the attach menu opens on a phone (`CameraSheet` of `pi-chat-attachments`). Without it there is no Take a photo entry. */
  readonly Camera?: ComponentType<CameraSheetProps> | undefined;
}

/** One past conversation in the history list. `title` is its name or first message; `updatedAt` is when it last had activity. */
export interface ConversationItem {
  readonly id: string;
  readonly title?: string | undefined;
  readonly updatedAt?: number | string | Date | undefined;
  /** A preview of the last message (the row's tooltip). */
  readonly lastMessage?: string | null | undefined;
  readonly archived?: boolean | undefined;
}
/** The host's conversations. Give it to `PiChat` and the header's History button opens a list of them instead of the earlier records of this one. */
export interface ConversationsConfig {
  readonly items: readonly ConversationItem[];
  /** The conversation that is open; it is marked in the list. */
  readonly activeId?: string | undefined;
  readonly onSelect: (id: string) => void;
  readonly onNew?: (() => void) | undefined;
  readonly loading?: boolean | undefined;
  /**
   * Server-side search: with it, a typed query (or the Archived filter) lists what this returns instead of filtering `items`
   * by title. Abort `signal` when the query changes.
   */
  readonly search?: ((query: string, options: { readonly archived: boolean }, signal: AbortSignal) => Promise<readonly ConversationItem[]>) | undefined;
  /** Each action below adds its button to the rows; the host refreshes `items` when it resolves. */
  readonly rename?: ((id: string, title: string) => Promise<void>) | undefined;
  /** Archive (`true`) or restore (`false`). With it, the list also offers an Archived filter (which needs `search`). */
  readonly archive?: ((id: string, archived: boolean) => Promise<void>) | undefined;
  readonly remove?: ((id: string) => Promise<void>) | undefined;
  /** Fork the open conversation after the entry of a settled reply: the reply's Fork button. */
  readonly fork?: ((atEntryId: string) => Promise<void>) | undefined;
  /**
   * Host actions on each row, after rename, archive and delete: `header` ones as buttons, `menu` ones in a "…" menu. Test ids
   * `conversation-action-<id>`, the menu `conversation-action-more`.
   */
  readonly rowActions?: ((item: ConversationItem) => readonly BlockAction[]) | undefined;
}

/** A settled reply, as host message actions receive it: its row key, its text and the native entry it ends with. */
export interface ReplyRef {
  readonly key: string; readonly text: string; readonly entryId?: string | undefined;
  /** When the last model round of the reply was written (ms), the same value as its message's `timestamp`: a host keys its own per-reply data on it. */
  readonly timestamp?: number | undefined;
  /** The model that wrote the last round of the reply, as its message names it (`provider` and `model` ids). */
  readonly model?: { readonly provider: string; readonly modelId: string } | undefined;
  /**
   * Sum of the model rounds that form the reply (ms): Pi's own `AssistantMessage.durationMs`, measured monotonically
   * and kept in the transcript. It excludes queue time, tool runs and retry delays, and is absent for a message written
   * before Pi recorded it. It is never computed from the clock at render time.
   */
  readonly durationMs?: number | undefined;
}

export interface ModelRef { readonly provider: string; readonly modelId: string }
export interface ModelConfig {
  readonly options: readonly (ModelRef & { readonly label?: string })[];
  /** Reject to refuse: the message is shown inline. */
  readonly change: (model: ModelRef) => Promise<void>;
  /** The one model-and-effort pill (`ModelEffortPicker` of `pi-chat-pickers`; `effort.Picker` is used when only it is set). Without one there is no pill. */
  readonly Picker?: ComponentType<ModelEffortPickerProps> | undefined;
}
export interface EffortConfig {
  readonly options: readonly string[];
  readonly change: (level: string) => Promise<void>;
  /** The one model-and-effort pill, when `model` does not carry one (`ModelEffortPicker` of `pi-chat-pickers`). */
  readonly Picker?: ComponentType<ModelEffortPickerProps> | undefined;
}

/** The unified, internal menu entry. */
export interface SlashItem {
  readonly name: string;
  readonly description: string;
  readonly source: SlashSource;
  readonly sourcePlugin?: string;
}

export function slashItems(config: SlashConfig): SlashItem[] {
  return [
    ...(config.commands ?? []).map((command): SlashItem => ({ name: command.name, description: command.description ?? '', source: 'local', ...(command.sourcePlugin ? { sourcePlugin: command.sourcePlugin } : {}) })),
    ...(config.skills ?? []).map((skill): SlashItem => ({ name: skill.name, description: skill.description, source: 'skill', ...(skill.sourcePlugin ? { sourcePlugin: skill.sourcePlugin } : {}) })),
  ];
}

/** The group an item lives under in the filter chips: skills, its plugin, or `built-in`. */
export function slashGroup(item: Pick<SlashItem, 'source' | 'sourcePlugin'>): string {
  if (item.source === 'skill') return 'skills';
  return item.sourcePlugin || 'built-in';
}

/** `/` opens the menu only when the text before the caret is one `/token`, as in v2. */
export function slashQuery(text: string, caret: number): string | null {
  const match = /^\/(\S*)$/.exec(text.slice(0, caret));
  return match ? match[1]! : null;
}

export interface MentionTrigger { readonly query: string; readonly start: number; readonly end: number }
/** An `@` at the start or after whitespace, up to the caret. */
export function mentionTrigger(text: string, caret: number): MentionTrigger | null {
  const before = text.slice(0, caret);
  const match = /(^|\s)@(\S*)$/.exec(before);
  // A typed opening quote (`@"Meeting`) is not part of the search; the token starts at the `@` either way.
  return match ? { query: match[2]!.replace(/^"/, ''), start: before.length - match[2]!.length - 1, end: caret } : null;
}

/**
 * The text of a mention of `path`. A path with whitespace or a quote is written in double quotes, `@"docs/Meeting notes.md"`, with `\`
 * and `"` escaped, because a bare mention ends at a space. Any other path stays bare (`@docs/plan.md`), as it always was.
 */
export function mentionToken(path: string): string {
  return /[\s"]/.test(path) ? `@"${path.replace(/[\\"]/g, '\\$&')}"` : `@${path}`;
}
/**
 * The `@` tokens of a message, bare or quoted: group 1 is the character before the `@` (or the start), group 2 the quoted body (escapes
 * still in it), group 3 the bare path. `test/contracts/pi-chat-source.test.mjs` keeps `mentionedPaths` in the agent package equal to this.
 */
export const MENTION_TOKEN = /(^|\s)@(?:"((?:[^"\\]|\\.)*)"|([^\s]+))/g;

const escape = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const BOUNDARY = '[^A-Za-z0-9_./-]';
export function hasMention(text: string, path: string): boolean {
  return new RegExp(`(^|${BOUNDARY})${escape(mentionToken(path))}($|${BOUNDARY})`).test(text);
}
export function removeMention(text: string, path: string): string {
  return text.replace(new RegExp(`(^|${BOUNDARY})${escape(mentionToken(path))}(?=$|${BOUNDARY})[ ]?`), '$1').replace(/^[ ]+/, '');
}

export type Piece = { readonly text: string; readonly kind?: 'mention' | 'skill'; readonly value?: string };

/** Upload paths are `uploads/<name>`: the attachments of a message, shown as cards rather than as text. */
export const isUploadPath = (path: string): boolean => path.startsWith('uploads/');

export type FileKind = 'document' | 'image' | 'pdf' | 'sheet' | 'slides' | 'audio' | 'file';
const KIND_BY_EXTENSION: Readonly<Record<string, FileKind>> = {
  png: 'image', jpg: 'image', jpeg: 'image', gif: 'image', webp: 'image', svg: 'image', bmp: 'image', avif: 'image',
  pdf: 'pdf',
  webm: 'audio', ogg: 'audio', m4a: 'audio', mp4: 'audio', mp3: 'audio', wav: 'audio',
  csv: 'sheet', tsv: 'sheet', xls: 'sheet', xlsx: 'sheet', xlsm: 'sheet', ods: 'sheet', numbers: 'sheet',
  ppt: 'slides', pptx: 'slides', odp: 'slides', key: 'slides',
  md: 'document', markdown: 'document', txt: 'document', doc: 'document', docx: 'document', odt: 'document', rtf: 'document',
};
/** The card's kind, from the extension alone. */
export function fileKind(path: string): FileKind {
  const extension = /\.([^./]+)$/.exec(path)?.[1]?.toLowerCase() ?? '';
  return KIND_BY_EXTENSION[extension] ?? 'file';
}
/** Recorded voice uses a reserved upload filename prefix; other audio remains a plain file card. */
export const isVoicePath = (path: string): boolean => /^uploads\/voice-[^/]+$/.test(path) && fileKind(path) === 'audio';

/** The name a card shows: the upload's file name without the random suffix `uploadPath` adds (`report-1a2b3c4d.pdf` is `report.pdf`). */
export function displayName(path: string): string {
  const name = path.slice(path.lastIndexOf('/') + 1);
  return name.replace(/-[0-9a-f]{8}(?=\.[^.]*$|$)/i, '');
}

/**
 * The pieces a message shows once `hidden` ones are taken out: a space that a removed piece leaves at a join is dropped, and the ends are
 * trimmed where it was. The message's own text is not changed, only what the bubble draws.
 */
export function visibleParts(parts: readonly Piece[], hidden: (part: Piece) => boolean): Piece[] {
  const out: Piece[] = [];
  let gap = false;
  for (const part of parts) {
    if (hidden(part)) { gap = true; continue; }
    const prev = out[out.length - 1];
    const joins = gap && part.kind === undefined && (prev === undefined || (prev.kind === undefined && /\s$/.test(prev.text)));
    out.push(joins ? { text: part.text.replace(/^\s+/, '') } : part);
    gap = false;
  }
  const last = out[out.length - 1];
  if (gap && last && last.kind === undefined) out[out.length - 1] = { text: last.text.replace(/\s+$/, '') };
  return out.filter(part => part.kind !== undefined || part.text !== '');
}

/** Whether pasted text is long enough to become a file. `more` than the limits: the characters, or the lines, of the text. */
export function isLongPaste(text: string, limits: PasteToFile = {}): boolean {
  const { minChars = 2000, minLines = 40 } = limits;
  return text.length > minChars || text.split('\n').length > minLines;
}
/** Markdown in pasted text: a heading, a list or quote item, a fence, a table row, emphasis or a link. Anything else is plain text. */
export function looksLikeMarkdown(text: string): boolean {
  return /^\s{0,3}(#{1,6}\s|[-*+]\s|\d+[.)]\s|>\s|```|~~~)/m.test(text) || /\*\*[^*\n]+\*\*|\]\([^)\n]+\)|^\|.*\|\s*$/m.test(text);
}
/** Split a sent message into plain text, `@path` mentions and a leading `/skill` token. */
export function pieces(text: string, options: { readonly mentions: boolean; readonly skills: readonly string[]; readonly uploads?: boolean }): Piece[] {
  const found: { start: number; end: number; kind: 'mention' | 'skill'; value: string }[] = [];
  const skill = options.skills.length ? new RegExp(`^/(${options.skills.map(escape).join('|')})(?=\\s|$)`).exec(text) : null;
  if (skill) found.push({ start: 0, end: skill[0].length, kind: 'skill', value: skill[1]! });
  if (options.mentions || options.uploads) {
    for (const match of text.matchAll(MENTION_TOKEN)) {
      // A quoted path keeps its punctuation (the closing quote ends it); a bare one drops trailing punctuation, as a sentence would.
      const quoted = match[2] !== undefined;
      const path = quoted ? match[2]!.replace(/\\(.)/g, '$1') : match[3]!.replace(/[.,;:!?)\]}'"]+$/, '');
      if (!path || (!options.mentions && !isUploadPath(path))) continue;
      const start = match.index! + match[1]!.length;
      const end = quoted ? match.index! + match[0].length : start + 1 + path.length;
      found.push({ start, end, kind: 'mention', value: path });
    }
  }
  const out: Piece[] = [];
  let cursor = 0;
  for (const item of found.sort((a, b) => a.start - b.start)) {
    if (item.start < cursor) continue;
    if (item.start > cursor) out.push({ text: text.slice(cursor, item.start) });
    out.push({ text: text.slice(item.start, item.end), kind: item.kind, value: item.value });
    cursor = item.end;
  }
  if (cursor < text.length) out.push({ text: text.slice(cursor) });
  return out;
}

