export type ToolStatus = 'running' | 'completed' | 'failed' | 'unfinished';
export interface ToolEntry { readonly key: string; readonly call: ToolCall; readonly result: ToolResultMessage | undefined; readonly status: ToolStatus; readonly custom?: ReactNode }

const STATUS_LABEL = { running: 'toolRunning', completed: 'toolCompleted', failed: 'toolFailedStatus', unfinished: 'toolUnfinished' } as const satisfies Record<ToolStatus, keyof ChatLabels>;
const PREVIEW_KEYS = ['path', 'file_path', 'filePath', 'command', 'query', 'pattern', 'name', 'url', 'id'];

/** A short hint of what the call acts on, shown next to its name. */
export function preview(args: ToolCall['arguments']): string {
  const values = args as Record<string, unknown>;
  for (const key of PREVIEW_KEYS) { const value = values[key]; if (typeof value === 'string' && value) return value.replace(/\s+/g, ' ').slice(0, 90); }
  const first = Object.values(values).find(value => typeof value === 'string' && value);
  return typeof first === 'string' ? first.replace(/\s+/g, ' ').slice(0, 90) : '';
}

function Section({ title, children }: { readonly title: string; readonly children: ReactNode }) {
  return <div className="space-y-1.5"><h4 className="m-0 text-xs font-medium tracking-wider text-muted-foreground uppercase">{title}</h4>{children}</div>;
}

/** A short live label for a call: "Reading notes/consultation.md", "Running bash", "Running working_git" (`labels.toolActivity`). */
export function liveLabel(call: ToolCall, labels: Pick<ChatLabels, 'toolActivity'> = defaultChatLabels): string {
  return labels.toolActivity(call.name, preview(call.arguments));
}

/** One Trace step. Failures open by default; quiet successful steps have no disclosure. */
export function ToolCard({ entry, onOpenImage, details = true }: { readonly entry: ToolEntry; readonly details?: boolean; readonly onOpenImage?: (image: Extract<ToolResultMessage['content'][number], { type: 'image' }>) => void }) {
  const { labels } = useChatText();
  const [chosen, setChosen] = useState<boolean | undefined>();
  const { call, result, status } = entry;
  const open = details && (chosen ?? status === 'failed');
  const hint = preview(call.arguments);
  const line = <TraceLine {...(status === 'running' ? { status: 'running' } : status === 'failed' ? { status: 'error' } : {})}>
    <TraceIcon><WrenchIcon /></TraceIcon>
    <TraceTitle><span data-testid="tool-name">{call.name}</span>{hint && ` · ${hint}`}</TraceTitle>
    <TraceDescription data-testid="tool-status">{labels[STATUS_LABEL[status]]}</TraceDescription>
  </TraceLine>;
  return <TraceCollapsible data-testid="tool-card" data-boring="tool-card" data-status={status} data-tool={call.name} data-call-id={call.id} open={open} onOpenChange={setChosen}>
    {details ? <TraceCollapsibleTrigger className="min-h-8 max-sm:min-h-11 pointer-coarse:min-h-11">{line}</TraceCollapsibleTrigger> : line}
    {details && <TraceCollapsibleContent><div data-testid="tool-details" className="flex flex-col gap-3">
      <Section title={labels.arguments}><Card><CardContent><pre className="m-0 max-h-60 overflow-auto whitespace-pre-wrap [overflow-wrap:anywhere]">{JSON.stringify(call.arguments, null, 2)}</pre></CardContent></Card></Section>
      {result && <Section title={result.isError ? labels.error : labels.result}>
        <Alert variant={result.isError ? 'destructive' : 'default'} role={result.isError ? 'alert' : 'status'}><AlertDescription>
          {result.content.map((part, index) => part.type === 'text'
            ? <pre key={index} className="m-0 max-h-72 overflow-auto whitespace-pre-wrap [overflow-wrap:anywhere]">{part.text}</pre>
            : <Button key={index} variant="outline" size="sm" className="max-sm:min-h-12! pointer-coarse:min-h-12!" disabled={!onOpenImage} onClick={() => onOpenImage?.(part)}>{labels.openImageResult}</Button>)}
          {result.content.length === 0 && <span>{labels.emptyResult}</span>}
        </AlertDescription></Alert></Section>}
    </div></TraceCollapsibleContent>}
  </TraceCollapsible>;
}

import { useEffect, useLayoutEffect, useMemo, useState } from 'react';
import { createNativeChatController } from '@hachej/boring-ui-kit/native-chat';
import type { ChatIdentity, NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import type { ChatController } from '@hachej/boring-ui-kit/native-chat';
import { createRemoteChat } from '@hachej/boring-ui-kit/remote-chat';
import type { RemoteChat, RemoteChatOptions } from '@hachej/boring-ui-kit/remote-chat';
import type { PiChatActions } from './session';

// ---- Placement: where the chat is shown, reported by the component that shows it and sent with each submit (see `useRemoteChat`).
// `PiChat` reports `docked`, `AmbientChat` (also a docked chat floated by its divider) reports `floating`. Advisory for the model, never
// authority. See docs/architecture/PAGE-TOOLS.md (PLACE-1..3).
export type ChatPlacement = 'docked' | 'floating';

// Keyed by controller (a page can hold several chats; floating or docking keeps the controller, PLACE-3). Each mounted presenter has its own
// registration, so unmounting one never clears another's; the latest surviving registration wins.
const placements = new WeakMap<ChatController, { readonly placement: ChatPlacement }[]>();

/** Reports the placement of the chat showing `controller` while the caller is mounted. */
export function useChatPlacement(controller: ChatController, placement: ChatPlacement): void {
  useLayoutEffect(() => {
    const entry = { placement };
    const list = placements.get(controller) ?? [];
    placements.set(controller, [...list, entry]);
    return () => {
      const rest = (placements.get(controller) ?? []).filter(item => item !== entry);
      if (rest.length) placements.set(controller, rest); else placements.delete(controller);
    };
  }, [controller, placement]);
}

export function readChatPlacement(controller: ChatController | undefined): ChatPlacement | undefined {
  return controller ? placements.get(controller)?.at(-1)?.placement : undefined;
}

export type RemoteChatState =
  | { readonly status: 'connecting'; readonly conversationId: string | undefined }
  | { readonly status: 'offline'; readonly conversationId: string | undefined; readonly error: string }
  | { readonly status: 'ready'; readonly conversationId: string; readonly controller: NativeChatController; readonly actions: PiChatActions; readonly configure: RemoteChat['configure'] };

/**
 * One native chat controller per selected conversation over the host's chat transport (`createChatTransportHandler` of
 * `@hachej/boring-agent/chat-transport`). `endpoint(id)` names the transport URL of a conversation; `fetch` is the host's authenticated fetch.
 * The remote chat reopens a dropped stream itself (the controller reads `reconnecting` meanwhile); it never means the task stopped.
 * A failed connect retries every second. The previous conversation's controller is never handed out: it is disposed on change.
 */
export function useRemoteChat({ conversationId, endpoint, fetch, identity, requestContext, transport, webSocket }: {
  readonly conversationId: string | undefined;
  readonly endpoint: (conversationId: string) => string | URL;
  readonly fetch: (request: Request) => Promise<Response>;
  readonly identity: ChatIdentity | undefined;
  /**
   * The current screen context, read at each submit (for example `readAgentContext` of the app-shell item). The submit's `context` is this
   * value as it is (so a host reading `name` and `params` keeps working) plus `placement`: `docked` or `floating`, reported by the chat.
   */
  readonly requestContext?: () => Readonly<Record<string, unknown>> | undefined;
  /** `websocket`: one hibernation-friendly socket instead of the HTTP watch stream, falling back to HTTP (see `createRemoteChat`). Read when a conversation connects. */
  readonly transport?: RemoteChatOptions['transport'];
  readonly webSocket?: RemoteChatOptions['webSocket'];
}): RemoteChatState {
  const url = conversationId === undefined ? undefined : String(endpoint(conversationId));
  const key = JSON.stringify([conversationId, url, identity?.runtimeId, identity?.scopeId, identity?.principalId, transport]);
  const binding = useMemo(() => ({ key, fetch, requestContext, webSocket }), [key]); // eslint-disable-line react-hooks/exhaustive-deps
  useLayoutEffect(() => { binding.fetch = fetch; binding.requestContext = requestContext; binding.webSocket = webSocket; }, [binding, fetch, requestContext, webSocket]);
  const [stored, setStored] = useState<{ readonly binding: typeof binding; readonly chat: RemoteChatState }>();
  useEffect(() => {
    if (conversationId === undefined || !identity || url === undefined) return;
    const setChat = (chat: RemoteChatState) => setStored({ binding, chat });
    let disposed = false, controller: NativeChatController | undefined, remote: RemoteChat | undefined;
    const context = () => {
      const placement = readChatPlacement(controller), screen = binding.requestContext?.();
      return placement || screen ? { ...screen, ...(placement && { placement }) } : undefined;
    };
    setChat({ status: 'connecting', conversationId });
    void (async () => {
      while (!disposed) {
        try {
          remote = await createRemoteChat({ endpoint: url, fetch: request => binding.fetch(request), requestContext: context, ...(transport ? { transport } : {}), ...(binding.webSocket ? { webSocket: binding.webSocket } : {}) });
          if (disposed) return void remote.close();
          controller = createNativeChatController({ identity, ...remote });
          await controller.connect();
          if (disposed) return void controller.dispose();
          // Human-in-the-loop answers and queue withdrawal are optional on the transport: pass only what it offers.
          const actions: { answer?: RemoteChat['answer']; withdraw?: RemoteChat['withdraw'] } = {};
          if (typeof remote.answer === 'function') actions.answer = remote.answer;
          if (typeof remote.withdraw === 'function') actions.withdraw = remote.withdraw;
          setChat({ status: 'ready', controller, conversationId, actions, configure: remote.configure });
          return;
        } catch (error) {
          controller?.dispose(); controller = undefined; void remote?.close(); remote = undefined;
          if (disposed) return;
          setChat({ status: 'offline', conversationId, error: String((error as Error)?.message ?? error) });
          await new Promise(resolve => setTimeout(resolve, 1000));
        }
      }
    })();
    return () => { disposed = true; controller?.dispose(); void remote?.close(); };
  }, [binding]); // eslint-disable-line react-hooks/exhaustive-deps
  return identity && stored?.binding === binding ? stored.chat : { status: 'connecting', conversationId };
}

'use client';

import { useEffect, useRef } from 'react';
import type { ChatController } from '@hachej/boring-ui-kit/native-chat';

const PREFIX = 'pi-chat:draft:';

/** The stored draft: a string, `null` when the key is missing, `undefined` when storage is unavailable (missing, blocked or throwing). */
function read(storageKey: string): string | null | undefined {
  try {
    const storage = globalThis.localStorage;
    return storage ? storage.getItem(storageKey) : undefined;
  } catch { return undefined; }
}
function write(storageKey: string, text: string): void {
  try { if (text) globalThis.localStorage?.setItem(storageKey, text); else globalThis.localStorage?.removeItem(storageKey); } catch { /* the composer still holds the text */ }
}

/**
 * Keeps the composer's half-typed message (the controller's draft) per conversation in localStorage, so it survives a reload and shows in
 * every tab on the same conversation (the `storage` event). The draft is emptied when a message is sent, and a refused send puts the text back,
 * which is written again. Without `key` nothing happens. Storage that is missing or throws only means the draft is not kept.
 *
 * On mount the conversation's saved draft replaces the composer's text; text already in the composer and not yet saved is written at once.
 * On a change of `key` (same controller) the composer shows the new conversation's saved draft, or an empty one, so no text moves across.
 */
export function useChatDraft(controller: ChatController, key: string | undefined): void {
  // The key the hook last loaded; a different key on a later run is a conversation switch, not a first mount.
  const loaded = useRef<string | undefined>(undefined);
  useEffect(() => {
    if (key === undefined || controller.getSnapshot().disposed) return;
    const storageKey = PREFIX + key;
    const switched = loaded.current !== undefined && loaded.current !== key;
    loaded.current = key;
    const stored = read(storageKey);
    const current = controller.getSnapshot().draft.text;
    // The text last known to be in storage; a write happens only when the composer's text differs from it.
    let saved: string;
    if (stored) {
      if (stored !== current) controller.setText(stored);
      saved = stored;
    } else if (switched) {
      // The new conversation has no saved draft (or storage is unavailable): the old conversation's text must not stay.
      if (current) controller.setText('');
      saved = '';
    } else {
      saved = current;
      if (stored === null && current) write(storageKey, current);
    }
    const persist = () => {
      if (controller.getSnapshot().disposed) return;
      const text = controller.getSnapshot().draft.text;
      if (text === saved) return;
      saved = text;
      write(storageKey, text);
    };
    const unsubscribe = controller.subscribe(persist);
    // Another tab changed this conversation's draft (or cleared all storage: `key` is null). Adopting it does not write it back.
    // Unavailable storage is not a missing draft: the composer keeps its text.
    const onStorage = (event: StorageEvent) => {
      if (event.key !== null && event.key !== storageKey) return;
      if (controller.getSnapshot().disposed) return;
      const next = read(storageKey);
      if (next === undefined) return;
      const text = next ?? '';
      saved = text;
      if (text !== controller.getSnapshot().draft.text) controller.setText(text);
    };
    globalThis.addEventListener?.('storage', onStorage);
    return () => {
      unsubscribe();
      globalThis.removeEventListener?.('storage', onStorage);
    };
  }, [controller, key]);
}

/* The languages the chat ships with. `locale` picks the base words; a host's `labels` still override any of them. */
import { defaultChatIcons, defaultChatText } from './labels';
import type { ChatText } from './labels';
import { frenchChatLabels } from './labels-fr';

export type ChatLocale = 'en' | 'fr';
const TEXT: Readonly<Record<ChatLocale, ChatText>> = { en: defaultChatText, fr: { labels: frenchChatLabels, icons: defaultChatIcons } };
/** The chat's base labels and icons for `locale` (English by default). */
export const chatTextFor = (locale: ChatLocale | undefined): ChatText => TEXT[locale ?? 'en'];

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { ConversationItem, ConversationsConfig } from './config';

/** One row as `createConversationsHandler` of `@hachej/boring-agent/conversations` returns it. */
interface ServedConversation {
  readonly id: number | string;
  readonly title: string | null;
  readonly lastMessage: string | null;
  readonly updatedAt: number;
  readonly archived: boolean;
}

const item = (served: ServedConversation): ConversationItem => ({ id: String(served.id), title: served.title ?? undefined, updatedAt: served.updatedAt, lastMessage: served.lastMessage, archived: served.archived });

/**
 * The sessions list over the host's conversations handler (`createConversationsHandler` of `@hachej/boring-agent/conversations`, mounted at
 * `endpoint`): the active list (polled every `pollMs` while mounted), server-side search with the Archived filter, New, rename, archive,
 * delete and fork. New and fork select the conversation they made through `onSelect`. `onChange` runs after every change the person made
 * (the host may reload what depends on the list). `fetch` is the host's authenticated fetch. Returns `undefined` until the first list arrives.
 */
export function useConversations({ endpoint, fetch, activeId, onSelect, onChange, pollMs = 4000 }: {
  /** Undefined: nothing is listed yet (for example while the host is still loading). */
  readonly endpoint: string | URL | undefined;
  readonly fetch: (request: Request) => Promise<Response>;
  readonly activeId: string | undefined;
  readonly onSelect: (id: string) => void;
  readonly onChange?: (() => void | Promise<void>) | undefined;
  readonly pollMs?: number;
}): (ConversationsConfig & { readonly reload: () => Promise<void> }) | undefined {
  const [items, setItems] = useState<readonly ConversationItem[] | undefined>();
  const latest = useRef({ fetch, onSelect, onChange, activeId });
  latest.current = { fetch, onSelect, onChange, activeId };
  const base = endpoint === undefined ? undefined : String(endpoint);
  const call = useCallback(async (params: Record<string, string>, body?: unknown, signal?: AbortSignal) => {
    if (base === undefined) throw new Error('No conversations endpoint');
    const url = new URL(base, globalThis.location?.href);
    for (const [key, value] of Object.entries(params)) url.searchParams.set(key, value);
    const init: RequestInit = body === undefined ? { ...(signal ? { signal } : {}) } : { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body), ...(signal ? { signal } : {}) };
    const response = await latest.current.fetch(new Request(url, init));
    if (!response.ok) throw new Error(`Conversations: ${response.status}`);
    return await response.json() as { conversations?: readonly ServedConversation[]; conversationId?: number | string };
  }, [base]);
  const reload = useCallback(async () => { const result = await call({}); setItems((result.conversations ?? []).map(item)); }, [call]);
  // Another endpoint (another owner's list) starts empty; switching conversations only reloads.
  useEffect(() => { setItems(undefined); }, [base]);
  useEffect(() => {
    if (base === undefined) return;
    let off = false;
    const load = () => call({}).then(result => { if (!off) setItems((result.conversations ?? []).map(item)); }).catch(() => {});
    void load();
    const timer = setInterval(load, pollMs);
    return () => { off = true; clearInterval(timer); };
  }, [call, pollMs, activeId]); // eslint-disable-line react-hooks/exhaustive-deps
  return useMemo(() => {
    if (!items) return undefined;
    const changed = async () => { await reload().catch(() => {}); await latest.current.onChange?.(); };
    const op = (name: string, body: unknown) => call({ op: name }, body);
    return {
      items, activeId, reload,
      onSelect: (id: string) => latest.current.onSelect(id),
      onNew: () => { void op('create', {}).then(async result => { await changed(); if (result.conversationId !== undefined) latest.current.onSelect(String(result.conversationId)); }).catch(() => {}); },
      search: async (query: string, { archived }: { readonly archived: boolean }, signal: AbortSignal) =>
        ((await call({ ...(query ? { q: query } : {}), ...(archived ? { archived: '1' } : {}) }, undefined, signal)).conversations ?? []).map(item),
      rename: async (id: string, title: string) => { await op('rename', { conversationId: id, title }); await changed(); },
      archive: async (id: string, archived: boolean) => { await op('archive', { conversationId: id, archived }); await changed(); },
      remove: async (id: string) => { await op('delete', { conversationId: id }); await changed(); },
      fork: async (at: string) => {
        const from = latest.current.activeId;
        if (from === undefined) return;
        const { conversationId } = await op('fork', { conversationId: from, at });
        await changed();
        if (conversationId !== undefined) latest.current.onSelect(String(conversationId));
      },
    };
  }, [items, activeId, call, reload]);
}
